Voici une fonction C++ qui prend une référence à un `std::string` contenant du texte au format Markdown et renvoie un `std::string` contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Mapping Markdown syntax to HTML tags
const std::unordered_map<std::string, std::string> MarkdownToHtml {
    {"h1", "<h1>"},
    {"h2", "<h2>"},
    {"h3", "<h3>"},
    {"h4", "<h4>"},
    {"h5", "<h5>"},
    {"h6", "<h6>"},
    {"strong", "<strong>"},
    {"em", "<em>"},
    {"code", "<code>"},
    {"blockquote", "<blockquote>"},
    {"ul", "<ul>"},
    {"ol", "<ol>"},
    {"li", "<li>"},
    {"a", "<a href=\"\\2\">\\1</a>"}, // Note: assumes URLs are in format: [URL](link)
    {"img", "<img src=\"\\2\" alt=\"\\1\">"} // Note: assumes image URLs are in format: ![alt text](image URL)
};

// Function to convert Markdown to HTML
std::string markdownToHtml(const std::string& markdown) {
    std::string html;

    // Replace line breaks with <br> tags
    std::regex lineBreaks(R"(\\n+)", std::regex::extended);
    std::string modifiedMarkdown = std::regex_replace(markdown, lineBreaks, "<br>\n");

    // Loop through each line in the modified Markdown
    std::string line;
    std::istringstream ss(modifiedMarkdown);
    while (std::getline(ss, line)) {
        std::string htmlLine;

        // Loop through each Markdown syntax in the line
        std::regex markdownRegexes(R"(\\[(.+?)\\](\\S+)|(?:(?:^|\\s)#+\\s(.+?\\S))|(?:^|\\s)\\*\\*(.+?\\S)\\*\\*(?:\\s|$)|(?:(?:^|\\s)\\*([^*\\\\]|\\\\.)+?\\*\\s)|(?:^|\\s)__(.+?\\S)__\\s|(?:^|\\s)`(.+?`\\S)`)|(?:^|\\s)>(.+?\\S)\\s|(?:(?:^|\\s)\\-|\\*|-){2,}(.+?\\S)(?:\\s|$)|(?:(?:^|\\s)\\+|-){2,}(.+?\\S)(?:\\s|$)|(?:(?:^|\\s)\\=(?:-.|-|\\+|= ){1,})(.+?\\S)(?:\\s|$)|(?:(?:^|\\s)\\~\\~(.+?\\S)\\~\\~)|(?:^|\\s)\\.(.+?\\S)(?:\\s|$)|(?:(?:^|\\s)\\!\\[:?(.+?)\\]\\()([^\)]+?)\\))|(?:(?:^|\\s)\\!\\[(.+?)\\]\\(([^\\)]+?)\\))|(?:(?:^|\\s)\\!\\[(?:.+?)\\])|(?:^|\\s)\\!(.+?\\S)(?:\\s|$)|(?:^|\\s)\\?\\[(.+?)\\]\\(([^\\)]+?)\\))|(?:(?:^|\\s)\\?\\[(.+?)\\])|(?:^|\\s)\\?(.+?\\S)(?:\\s|$)|(?:^|\\s)\\~\\[(.+?)\\]\\(([^\\)]+?)\\))|(?:(?:^|\\s)\\~\\[(.+?)\\])|(?:^|\\s)\\~(.+?\\S)(?:\\s|$)|(?:^|\\s)\\|\\[(.+?)\\]\\(([^\\)]+?)\\))|(?:(?:^|\\s)\\|\\[(.+?)\\])|(?:^|\\s)\\|(.+?\\S)(?:\\s|$))", std::regex::extended);

        std::smatch match;

        while (std::regex_search(line, match, markdownRegexes)) {
            std::string markdownSyntax = match[1].str();
            std::string value = match[2].str();

            // Check if Markdown syntax is in the mapping
            auto it = MarkdownToHtml.find(markdownSyntax);
            if (it != MarkdownToHtml.end()) {
                std::string htmlTag = it->second;
                // Replace placeholders in the HTML tag with the corresponding values
                std::regex placeholderRegex("\\\\(\\d+)");

                std::string htmlValue;
                std::regex_search(value, match, std::regex("\\A(.*?)(?:\\Z|\\s+)"));
                htmlValue = match[1].str();

                std::string htmlTagWithValues = std::regex_replace(htmlTag, placeholderRegex,
                    [htmlValue](const std::cmatch& match) {
                        std::size_t index = std::stoi(match.str(1));
                        return htmlValue.substr(index);
                    });

                htmlLine += htmlTagWithValues;
            } else {
                htmlLine += line;
            }

            line = match.suffix().str();
        }

        html += htmlLine;
    }

    return html;
}

int main() {
    std::string markdown = "## Heading\n"
                           "Text with **bold** and *italic*.\n"
                           "\n"
                           "An [example URL](https://example.com).\n"
                           "![Alt text](https://example.com/image.jpg)\n"
                           "\n"
                           "1. Item one\n"
                           "2. Item two\n"
                           "3. Item three\n"
                           "\n"
                           "> This is a blockquote.\n"
                           "- Bullet point\n"
                           "+ Another bullet point\n"
                           "- Third bullet point\n"
                           " = Equal sign\n"
                           "~ Tilde\n"
                           ". Sentence\n"
                           "! This is an exclamation\n"
                           "? This is a question\n"
                           "~ This is a tilde\n"
                           "| This is a pipe\n"
                           "~~ This is two tildes\n"
                           "``This is code.``";

    std::string html = markdownToHtml(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

This implementation uses regular expressions to identify and convert various Markdown syntax to their corresponding HTML tags. Note that this implementation assumes that URLs are in the format `[URL](link)` and image URLs are in the format `![alt text](image URL)`. If your input Markdown uses a different format, you'll need to modify the regular expressions accordingly.

