```

3. Créez un fichier de ressources qui contiendra les images nécessaires pour votre jeu, par exemple `resources.h`. Dans ce fichier, définissez les constantes pour les images :

```c
#ifndef RESOURCES_H
#define RESOURCES_H

extern SDL_Texture *snake_head;
extern SDL_Texture *snake_body;
extern SDL_Texture *food;

#endif
```

4. Créez un autre fichier pour charger les images depuis les fichiers, par exemple `load_resources.c`. Dans ce fichier, vous utiliserez la fonction `SDL_LoadBMP` pour charger les images :

```c
#include <SDL2/SDL.h>
#include "resources.h"

void load_resources(SDL_Renderer *renderer) {
    SDL_Surface *surface_snake_head = SDL_LoadBMP("snake_head.bmp");
    SDL_Surface *surface_snake_body = SDL_LoadBMP("snake_body.bmp");
    SDL_Surface *surface_food = SDL_LoadBMP("food.bmp");

    snake_head = SDL_CreateTextureFromSurface(renderer, surface_snake_head);
    SDL_FreeSurface(surface_snake_head);

    snake_body = SDL_CreateTextureFromSurface(renderer, surface_snake_body);
    SDL_FreeSurface(surface_snake_body);

    food = SDL_CreateTextureFromSurface(renderer, surface_food);
    SDL_FreeSurface(surface_food);
}
```

5. Ajoutez la fonction `load_resources` à votre fichier `main.c` juste après la création du rendu :

```c
